const browserPluginRoot = process.env.ZCODE_PLUGIN_ROOT ?? process.env.CLAUDE_PLUGIN_ROOT;
if (!browserPluginRoot) throw new Error('Browser plugin root is unavailable in the node_repl host');
const { join } = await import('node:path');
const { pathToFileURL } = await import('node:url');
const browserClientUrl = pathToFileURL(join(browserPluginRoot, 'scripts', 'browser-client.mjs')).href;
const { setupBrowserRuntime } = await import(browserClientUrl);
await setupBrowserRuntime({ globals: globalThis });
const browser = await agent.browsers.get('iab');
const tab=await browser.tabs.get('{{latestBrowserTabId}}');
await tab.playwright.getByLabel('Name', {exact:true}).fill('after move');
await tab.playwright.getByRole('button',{name:'Continue',exact:true}).click();
await nodeRepl.emitImage(await tab.screenshot());
({marker:'E2E_SPW_BROWSER_ACTION_DONE',e2eBrowserTabId:tab.id,snapshot:await tab.playwright.domSnapshot()});
